import test from 'node:test';import assert from 'node:assert/strict';import {createSyncSession} from '../../src/features/sync/session-cache.ts';
const id=n=>`00000000-0000-4000-8000-${String(n).padStart(12,'0')}`,connection={id:id(1),institution:'nubank'};
function session(n){let active=true;const listeners=new Set();return {assertUnlocked(){if(!active)throw Error();},getSnapshot:()=>({state:active?'unlocked':'locked'}),subscribe(f){listeners.add(f);return()=>listeners.delete(f);},lock(){active=false;for(const f of listeners)f();},id:id(n)};}
const asset={id:'investment:'+id(1)+':'+id(4),connectionId:id(1),institutionId:'nubank',product:'investment',amountCents:29,currency:'BRL',kind:'asset',relation:'unknown',asOf:'2026-10-23',grossCents:39,netCents:29,valueBasis:'net',assetClass:'fixed_income'};
const movement={source:'connection:'+id(1),accountId:id(2),externalId:id(3),amountCents:29,currency:'BRL',direction:'debit',type:'unknown',status:'posted',occurredAt:'2026-10-23',institutionId:'nubank',description:'SYNTHETIC_ONLY',categoryId:null};
test('domain-validated cache restore uses new local session scope and preserves exact cents',()=>{const s=session(5),cache=createSyncSession(s,()=>s.id,{enabled:true,privateDataApproved:true});cache.restoreCache({assets:[asset],movements:[movement]},[connection]);const snap=cache.exportCache();assert.equal(snap.assets[0].netCents,29);assert.equal(snap.movements[0].amountCents,29);assert.equal(JSON.stringify(snap).includes('ownerSubject'),false);const next=session(6),other=createSyncSession(next,()=>next.id,{enabled:true,privateDataApproved:true});other.restoreCache(snap,[connection]);assert.equal(other.queryMovements({month:'2026-10'}).totalCount,1);s.lock();assert.throws(()=>cache.exportCache());other.close();});
test('removed bank not restored and invalid financial cents rejected by existing domain',()=>{const s=session(5),cache=createSyncSession(s,()=>s.id,{enabled:true,privateDataApproved:true});cache.restoreCache({assets:[asset],movements:[movement]},[]);assert.equal(cache.exportCache().assets.length,0);assert.throws(()=>cache.restoreCache({assets:[{...asset,amountCents:0.291,netCents:0.291}],movements:[]},[connection]));cache.close();});
